export interface WorkEntry {
  id: string;
  title: string;
  details: string;
  finished: boolean;
}

export class WorkLedger {
  private entries: WorkEntry[];

  constructor(entries: readonly WorkEntry[] = []) {
    const ids = new Set<string>();
    this.entries = entries.map((entry, index) => {
      if (typeof entry.id !== "string" || entry.id.trim().length === 0) {
        throw new TypeError(`invalid id at index ${index}`);
      }
      if (typeof entry.title !== "string" || entry.title.trim().length === 0) {
        throw new TypeError(`invalid title at index ${index}`);
      }
      if (typeof entry.details !== "string" || typeof entry.finished !== "boolean") {
        throw new TypeError(`invalid entry at index ${index}`);
      }
      if (ids.has(entry.id)) throw new TypeError(`duplicate id: ${entry.id}`);
      ids.add(entry.id);
      return entry;
    });
  }

  all(): WorkEntry[] {
    return this.entries.map(entry => ({ ...entry }));
  }

  flip(id: string): boolean {
    const index = this.entries.findIndex(entry => entry.id === id);
    if (index < 0) return false;
    const entry = this.entries[index];
    this.entries[index] = { ...entry, finished: !entry.finished };
    return true;
  }
}

