import { WorkLedger } from './solution';
import type { WorkEntry } from './solution';

function ok(value: boolean, message: string): void {
  if (!value) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsTypeError(fn: () => void, message: string): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const input: WorkEntry[] = [
  { id: ' Task ', title: ' First ', details: '', finished: false },
  { id: 'task', title: 'Second', details: 'detail', finished: true }
];
const ledger = new WorkLedger(input);
input[0].id = 'changed';
input[0].title = 'changed';
input[0].details = 'changed';
input[0].finished = true;
input.push({ id: 'later', title: 'Later', details: '', finished: false });

equal(JSON.stringify(ledger.all()), JSON.stringify([
  { id: ' Task ', title: ' First ', details: '', finished: false },
  { id: 'task', title: 'Second', details: 'detail', finished: true }
]), 'constructor copies entries and preserves strings and order');
const exposed = ledger.all();
exposed[0].title = 'mutated';
exposed[0].finished = true;
exposed.pop();
equal(ledger.all()[0].title, ' First ', 'all returns fresh objects');
equal(ledger.all().length, 2, 'all returns a fresh array');

ok(ledger.flip(' Task '), 'exact ID flips');
equal(ledger.all()[0].finished, true, 'false becomes true');
ok(ledger.flip(' Task '), 'same ID can flip again');
equal(ledger.all()[0].finished, false, 'true becomes false');
ok(!ledger.flip('Task'), 'whitespace difference does not match');
ok(!ledger.flip('TASK'), 'case difference does not match');
const beforeUnknown = JSON.stringify(ledger.all());
ok(!ledger.flip(''), 'empty unknown ID returns false');
ok(!ledger.flip('missing'), 'unknown ID returns false');
equal(JSON.stringify(ledger.all()), beforeUnknown, 'unknown flip leaves ledger unchanged');

const empty = new WorkLedger();
equal(empty.all().length, 0, 'default ledger is empty');
ok(!empty.flip('anything'), 'empty ledger cannot flip');
new WorkLedger([]);

throwsTypeError(() => new WorkLedger([{ id: '', title: 'T', details: '', finished: false }]), 'empty ID');
throwsTypeError(() => new WorkLedger([{ id: 'id', title: ' \n ', details: '', finished: false }]), 'blank title');
throwsTypeError(() => new WorkLedger([{ id: 'id', title: 'T', details: 3 as unknown as string, finished: false }]), 'non-string details');
throwsTypeError(() => new WorkLedger([{ id: 'id', title: 'T', details: '', finished: 1 as unknown as boolean }]), 'non-boolean finished');
throwsTypeError(() => new WorkLedger([
  { id: 'same', title: 'One', details: '', finished: false },
  { id: 'same', title: 'Two', details: '', finished: true }
]), 'duplicate IDs');

